import {
	breakpoints,
	containers,
	elevation,
	icon,
	leading,
	radius,
	spacingScale,
	steps,
	tracking,
	typography
} from './index';

const HEADER = `/*
 * AUTO-GENERATED FILE — DO NOT EDIT.
 *
 * Source of truth: src/shared/design/tokens/tokens.ts (shared scale) and index.ts (web-only names).
 * Regenerated by the design-tokens Vite plugin and \`bun run tokens:build\`.
 * Edit the .ts source, not this file.
 */`;

const RESET_NAMESPACES = ['text', 'leading', 'radius', 'container', 'breakpoint'];

function px(value: number): string {
	return `${value}px`;
}

/**
 * Turns the token registry into the Tailwind v4 theme: the 4px step, a reset of every size namespace the
 * scale owns (so a Tailwind default such as `text-sm`, `max-w-md` or `sm:` stops compiling) followed by
 * our names, and the `icon-*` utilities. Pure: no side effects, no Node imports.
 */
export function tokensToCss(): string {
	const lines: string[] = ['@theme {', `\t--spacing: ${px(steps.base)};`];

	for (const namespace of RESET_NAMESPACES) lines.push(`\t--${namespace}-*: initial;`);

	for (const [name, role] of Object.entries(typography)) {
		lines.push(`\t--text-${name}: ${px(role.size)};`);
		lines.push(`\t--text-${name}--line-height: ${role.lineHeight};`);
		lines.push(`\t--text-${name}--font-weight: ${role.weight};`);
	}
	for (const [name, ratio] of Object.entries(leading)) lines.push(`\t--leading-${name}: ${ratio};`);
	for (const [name, value] of Object.entries(tracking))
		lines.push(`\t--tracking-${name}: ${value};`);
	for (const [name, value] of Object.entries(spacingScale))
		lines.push(`\t--spacing-${name}: ${value};`);
	for (const [name, value] of Object.entries(radius))
		lines.push(`\t--radius-${name}: ${px(value)};`);
	for (const [name, value] of Object.entries(elevation))
		lines.push(`\t--shadow-${name}: ${value};`);
	for (const [name, value] of Object.entries(containers)) {
		lines.push(`\t--container-${name}: ${px(value)};`);
	}
	for (const [name, value] of Object.entries(breakpoints)) {
		lines.push(`\t--breakpoint-${name}: ${px(value)};`);
	}
	lines.push('}', '');

	for (const [name, value] of Object.entries(icon)) {
		lines.push(`@utility icon-${name} {`, `\twidth: ${px(value)};`, `\theight: ${px(value)};`, '}');
	}

	return `${HEADER}\n\n${lines.join('\n')}\n`;
}
